import * as D from './domain-2cd6b06ecb42.mjs';
import {CATEGORIES,investmentKind,supplementDefaults} from './catalog-2cd6b06ecb42.mjs';
export function createCatalog({getState,openModal,closeModal,save,toast,entityReplace,configFields,readConfig,e}){
 function edit(id=null){
  const state=getState(),original=state.activities.find(a=>a.id===id),record=original??{id:D.uid(),name:'',category:'生活起居',color:'#648a73',favorite:true,mainline:false,mainSkillId:null,relatedSkillIds:[],archived:false};
  const categories=[...new Set([...CATEGORIES,...state.activities.map(a=>a.category)])];
  openModal(original?'活动设置':'新建活动',`<label>活动名称<input name="name" value="${e(record.name)}" maxlength="60" required autofocus></label><div class="form-row"><label>分类<select name="category">${categories.map(v=>`<option ${v===record.category?'selected':''}>${e(v)}</option>`).join('')}</select></label><label>颜色<input type="color" name="color" value="${e(record.color)}"></label></div><div class="checkbox-list"><label><input type="checkbox" name="favorite" ${record.favorite?'checked':''}>放在常用活动</label><label><input type="checkbox" name="mainline" ${record.mainline?'checked':''}>作为主线投入</label><label><input type="checkbox" name="archived" ${record.archived?'checked':''}>归档收起（历史保留）</label></div><label>手机使用约定<select name="phoneMode"><option value="parallel" ${record.phoneMode!=='focus'?'selected':''}>并行记录</option><option value="focus" ${record.phoneMode==='focus'?'selected':''}>专注：选定App切换，锁屏后恢复</option></select></label><p class="quiet-note">须在安卓端启用手机记录并选择干扰App后生效。</p>${configFields(record)}<p class="quiet-note">学习、运动分类会显示基础投入，不自动判断具体能力。设置只用于后续记录；历史保留原配置。</p>`,{onSubmit:async(f,op)=>{
   const next={...record,name:String(f.get('name')).trim(),category:f.get('category'),investmentKind:investmentKind(f.get('category')),color:f.get('color'),favorite:f.has('favorite'),mainline:f.has('mainline'),archived:f.has('archived'),phoneMode:f.get('phoneMode'),...readConfig(f)};
   await save(s=>entityReplace(s,'activities',original,next),{operationId:op});closeModal();toast('活动已保存');
  }});
 }
 function manage(){const state=getState();openModal('管理活动与培养关联',`<div class="activity-list">${state.activities.map(a=>`<div><span class="color-dot" style="background:${e(a.color)}"></span><div><strong>${e(a.name)}</strong><p>${a.archived?'已归档 · ':a.favorite?'常用 · ':''}${e(a.category)}</p></div><button type="button" class="secondary" data-action="edit-activity" data-id="${e(a.id)}">设置</button></div>`).join('')}</div><button type="button" class="primary full-width" data-action="new-activity">＋ 新建活动</button><button type="button" class="text-button" data-action="supplement-defaults">补充缺少的默认活动</button>`);}
 function choose(){const state=getState();openModal(state.running?'切换活动':'此刻，想记录什么？',`<div class="choose-grid">${state.activities.filter(a=>!a.archived).map(a=>`<button type="button" class="choose-option" data-action="quick-start" data-id="${e(a.id)}"><span class="color-dot" style="background:${e(a.color)}"></span><span>${e(a.name)}<small>${e(a.category)}</small></span>${state.running?.activityId===a.id?'<span class="tag">当前</span>':'<b>↗</b>'}</button>`).join('')}</div><button type="button" class="text-button" data-action="new-activity">＋ 自定义活动</button>`,{footer:state.running?'切换后，上一项在同一时刻结束。':'选择一项即可开始。'});}
 function supplement(){const state=getState(),next=supplementDefaults(state),added=next.activities.filter(a=>!state.activities.some(x=>x.id===a.id));openModal('补充默认目录',`<p>${added.length?'将补充：'+added.map(a=>e(a.name)).join('、'):'当前没有缺少的默认活动。'}</p><p>原有名称、分类、关联与历史保持。重名或相同ID不会重复添加。</p>`,{onSubmit:added.length?async()=>{await save(supplementDefaults);closeModal();toast('已补充默认活动');}:null});}
 return {edit,manage,choose,supplement};
}
